const incoming = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const firstName = String(incoming.firstName || incoming.first_name || '').trim() || 'N/A';
const lastName = String(incoming.lastName || incoming.last_name || '').trim() || 'N/A';
const email = String(incoming.email || '').trim() || 'N/A';
const phone = String(incoming.phone || '').trim() || 'N/A';
const pageUrl = String(incoming.pageUrl || '').trim() || 'N/A';
const leadSource = String(incoming.leadSource || incoming.source || '').trim() || 'N/A';
const utmSource = String(incoming.utmSource || '').trim() || 'N/A';
const utmMedium = String(incoming.utmMedium || '').trim() || 'N/A';
const utmCampaign = String(incoming.utmCampaign || '').trim() || 'N/A';
const message = String(incoming.message || '').trim() || 'N/A';
const alertTitle = String(incoming.alertTitle || incoming.eventTitle || '').trim() || 'New form submission (#leads)';

const text = [
  alertTitle,
  `firstName: ${firstName}`,
  `lastName: ${lastName}`,
  `email: ${email}`,
  `phone: ${phone}`,
  `leadSource: ${leadSource}`,
  `utmSource: ${utmSource}`,
  `utmMedium: ${utmMedium}`,
  `utmCampaign: ${utmCampaign}`,
  `pageUrl: ${pageUrl}`,
  `message: ${message}`
].join('\n');

return [{
  json: {
    text,
    sourcePayload: incoming
  }
}];

